#include <bits/stdc++.h>
using namespace std;
string readAll() {
    string s;
    char buf[1 << 16];
    size_t n;
    while ((n = fread(buf, 1, sizeof buf, stdin)) > 0) s.append(buf, n);
    return s;
}
int main() {
    string data = readAll();
    vector<string> lines;
    size_t start = 0;
    while (true) {
        size_t p = data.find('\n', start);
        if (p == string::npos) { lines.push_back(data.substr(start)); break; }
        lines.push_back(data.substr(start, p - start));
        start = p + 1;
    }
    int n = stoi(lines[0]);
    unordered_map<int, long long> freq;
    long long answer = 0;
    for (int i = 1; i <= n && i < (int)lines.size(); i++) {
        int mask = 0;
        for (char c : lines[i]) mask |= 1 << (c - 'a');
        auto &f = freq[mask];
        answer += f;
        f++;
    }
    cout << answer << '\n';
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (pos < buf.length && buf[pos] <= 32) pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > 32) pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= 32) pos++;
        boolean neg = buf[pos] == 45;
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > 32) r = r * 10 + (buf[pos++] - 48);
        return neg ? -r : r;
    }

    static int nextInt() { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        String[] lines = new String(System.in.readAllBytes()).split("\n", -1);
        int n = Integer.parseInt(lines[0].trim());
        HashMap<Integer, Integer> freq = new HashMap<>();
        long answer = 0;
        for (int i = 1; i <= n && i < lines.length; i++) {
            int mask = 0;
            for (int j = 0; j < lines[i].length(); j++) mask |= 1 << (lines[i].charAt(j) - 'a');
            int f = freq.getOrDefault(mask, 0);
            answer += f;
            freq.put(mask, f + 1);
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
	"bytes"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	lines := bytes.Split(data, []byte("\n"))
	n, _ := strconv.Atoi(string(bytes.TrimSpace(lines[0])))
	freq := map[int]int64{}
	var answer int64
	for i := 1; i <= n && i < len(lines); i++ {
		mask := 0
		for _, c := range lines[i] {
			mask |= 1 << (int(c) - 'a')
		}
		answer += freq[mask]
		freq[mask]++
	}
	w.WriteString(strconv.FormatInt(answer, 10) + "\n")
}
